package com.nicole.stillin;
import android.Manifest;import android.app.*;import android.os.*;import android.graphics.*;import android.hardware.Camera;import android.view.*;import android.widget.*;import java.io.*;
/** Captures directly to private cache. No external camera app and no gallery write. */
@SuppressWarnings("deprecation")
public class PrivateCamera extends Activity implements SurfaceHolder.Callback {
 Camera camera;SurfaceView preview;Button shutter;int rotation=90;boolean surfaceReady=false,capturing=false;TextView message;
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setFlags(8192,8192);getWindow().setStatusBarColor(0xff21182c);getWindow().setNavigationBarColor(0xff21182c);LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setBackgroundColor(0xff21182c);layout.setPadding(20,24,20,28);Button cancel=new Button(this);cancel.setText("Cancel · Private camera");cancel.setAllCaps(false);cancel.setOnClickListener(v->finish());layout.addView(cancel,new LinearLayout.LayoutParams(-1,55));message=new TextView(this);message.setText("Photos stay inside Still In?");message.setTextColor(Color.WHITE);message.setPadding(12,12,12,12);layout.addView(message);preview=new SurfaceView(this);layout.addView(preview,new LinearLayout.LayoutParams(-1,0,1));preview.getHolder().addCallback(this);shutter=new Button(this);shutter.setText("Take photo");shutter.setAllCaps(false);shutter.setTextColor(0xff30223f);shutter.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffedf5a2));shutter.setOnClickListener(v->capture());layout.addView(shutter,new LinearLayout.LayoutParams(-1,64));setContentView(layout);}
 public void surfaceCreated(SurfaceHolder h){surfaceReady=true;start(h);}
 public void surfaceChanged(SurfaceHolder h,int f,int w,int height){}
 public void surfaceDestroyed(SurfaceHolder h){surfaceReady=false;release();}
 void start(SurfaceHolder h){if(camera!=null)return;try{int chosen=0;Camera.CameraInfo info=new Camera.CameraInfo();for(int i=0;i<Camera.getNumberOfCameras();i++){Camera.getCameraInfo(i,info);if(info.facing==Camera.CameraInfo.CAMERA_FACING_BACK){chosen=i;break;}}Camera.getCameraInfo(chosen,info);rotation=info.orientation;camera=Camera.open(chosen);Camera.Parameters p=camera.getParameters();p.setRotation(0);if(p.getSupportedFocusModes().contains(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE))p.setFocusMode(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE);Camera.Size best=p.getSupportedPictureSizes().get(0);for(Camera.Size s:p.getSupportedPictureSizes())if(s.width>=1000&&s.width<best.width)best=s;p.setPictureSize(best.width,best.height);camera.setParameters(p);camera.setDisplayOrientation(rotation);camera.setPreviewDisplay(h);camera.startPreview();}catch(Exception e){message.setText("Camera unavailable. Close and try again.");release();}}
 void capture(){if(camera==null||capturing)return;capturing=true;shutter.setEnabled(false);try{camera.takePicture(null,null,(data,c)->{try{BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=2;Bitmap original=BitmapFactory.decodeByteArray(data,0,data.length,options);if(original==null)throw new IOException("No image");float scale=Math.min(1f,1000f/Math.max(original.getWidth(),original.getHeight()));Matrix m=new Matrix();m.postScale(scale,scale);m.postRotate(rotation);Bitmap rotated=Bitmap.createBitmap(original,0,0,original.getWidth(),original.getHeight(),m,true);File f=new File(getCacheDir(),"private-capture.jpg");try(FileOutputStream out=new FileOutputStream(f)){rotated.compress(Bitmap.CompressFormat.JPEG,80,out);}rotated.recycle();original.recycle();setResult(RESULT_OK);finish();}catch(Exception e){message.setText("Could not capture photo. Try again.");capturing=false;shutter.setEnabled(true);try{camera.startPreview();}catch(Exception ignored){}}});}catch(Exception e){capturing=false;shutter.setEnabled(true);message.setText("Camera is not ready. Try again.");}}
 void release(){if(camera!=null){try{camera.stopPreview();camera.release();}catch(Exception ignored){}camera=null;}}
 @Override protected void onPause(){release();super.onPause();}
 @Override protected void onResume(){super.onResume();if(surfaceReady)start(preview.getHolder());}
}
